using System;
using System.Collections.Generic;
using UnityEngine;

namespace AFJK.Rapier.Samples
{
    /// <summary>
    /// Reimplements the Rapier 3D JavaScript demo catalog using the Unity <b>component</b> layer
    /// (<see cref="RapierWorldComponent"/>, <see cref="RapierRigidBodyComponent"/>, the collider /
    /// joint / character-controller / PID components) instead of the low-level <c>RapierWorld</c>
    /// API. Every body in every demo is a GameObject with Rapier components attached, so the same
    /// scenes could equally be authored by hand, generated by Scene Sync, or driven by a network
    /// bridge. The world is stepped manually each <see cref="FixedUpdate"/> so per-demo pre-step
    /// logic (fountain spawning, kinematic platform, character/PID control) can run first.
    /// </summary>
    public sealed class RapierComponentDemosSample : MonoBehaviour
    {
        private enum DemoKind
        {
            CollisionGroups,
            CharacterController,
            ConvexPolyhedron,
            Ccd,
            Damping,
            Fountain,
            Heightfield,
            Joints,
            KevaTower,
            LockedRotations,
            Platform,
            Pyramid,
            TriangleMesh,
            Voxels,
            PidController,
            GlbToTrimesh,
            GlbToConvexHull
        }

        [SerializeField] private DemoKind demo = DemoKind.Pyramid;
        [SerializeField] private float timestep = 1f / 60f;
        [SerializeField] private bool runOnStart = true;
        [SerializeField] private bool running = true;
        [SerializeField] private int maxFountainBodies = 400;

        private static readonly DemoKind[] DemoValues =
        {
            DemoKind.CollisionGroups,
            DemoKind.CharacterController,
            DemoKind.ConvexPolyhedron,
            DemoKind.Ccd,
            DemoKind.Damping,
            DemoKind.Fountain,
            DemoKind.GlbToConvexHull,
            DemoKind.GlbToTrimesh,
            DemoKind.Heightfield,
            DemoKind.Joints,
            DemoKind.KevaTower,
            DemoKind.LockedRotations,
            DemoKind.PidController,
            DemoKind.Platform,
            DemoKind.Pyramid,
            DemoKind.TriangleMesh,
            DemoKind.Voxels
        };

        private static readonly string[] DemoNames =
        {
            "collision groups",
            "character controller",
            "convex polyhedron",
            "CCD",
            "damping",
            "fountain",
            "GLB to convex hull",
            "GLB to trimesh",
            "heightfield",
            "joints",
            "keva tower",
            "locked rotations",
            "PID controller",
            "platform",
            "pyramid",
            "triangle mesh",
            "voxels"
        };

        private GameObject generatedRoot;
        private GameObject worldGo;
        private RapierWorldComponent worldComponent;
        private string status = "Not started.";
        private Vector2 demoScroll;
        private int selectedDemoIndex;
        private int tick;
        private ulong lastHash;
        private bool rebuildRequested;
        private int nextBodyId;
        private int fountainSpawnCounter;
        private bool debugDraw;
        private Material debugMaterial;
        private Vector3[] debugVertices;
        private Color[] debugColors;

        private readonly Queue<GameObject> fountainBodies = new Queue<GameObject>();

        // Platform demo state.
        private RapierRigidBodyComponent platformBody;
        private float platformPhase;

        // Character controller demo state.
        private RapierCharacterControllerComponent characterController;

        // PID controller demo state.
        private RapierRigidBodyComponent pidBody;
        private RapierPidControllerComponent pidController;

        private void Start()
        {
            selectedDemoIndex = IndexOf(demo);
            if (runOnStart)
            {
                BuildDemo();
            }
        }

        private void Update()
        {
            if (!rebuildRequested)
            {
                return;
            }

            rebuildRequested = false;
            BuildDemo();
        }

        private void FixedUpdate()
        {
            if (!running || worldComponent == null || worldComponent.World == null || !worldComponent.World.IsCreated)
            {
                return;
            }

            switch (demo)
            {
                case DemoKind.Fountain:
                    PreStepFountain();
                    break;
                case DemoKind.Platform:
                    PreStepPlatform();
                    break;
                case DemoKind.CharacterController:
                    PreStepCharacter();
                    break;
                case DemoKind.PidController:
                    PreStepPidController();
                    break;
            }

            // RapierWorldComponent.Step() runs the simulation and syncs every registered body's
            // GameObject transform from Rapier, so the components themselves drive the visuals.
            if (!worldComponent.Step())
            {
                running = false;
                status = $"Rapier step failed at tick {tick}.";
                Debug.LogError(status, this);
                return;
            }

            tick++;
            lastHash = worldComponent.StateHash();
            status = $"{DemoNames[selectedDemoIndex]} running. Tick {tick}, hash {lastHash:x16}.";
        }

        private void OnDisable()
        {
            DestroyGeneratedRoot();

            if (debugMaterial != null)
            {
                DestroyImmediate(debugMaterial);
                debugMaterial = null;
            }
        }

        private void OnRenderObject()
        {
            if (!debugDraw || worldComponent == null || worldComponent.World == null || !worldComponent.World.IsCreated)
            {
                return;
            }

            const int maxLines = 8192;
            if (debugColors == null || debugColors.Length < maxLines)
            {
                debugColors = new Color[maxLines];
            }

            if (debugVertices == null || debugVertices.Length < maxLines * 2)
            {
                debugVertices = new Vector3[maxLines * 2];
            }

            var lines = worldComponent.World.DebugRender(debugVertices, debugColors);
            if (lines <= 0)
            {
                return;
            }

            EnsureDebugMaterial();
            debugMaterial.SetPass(0);
            GL.PushMatrix();
            GL.Begin(GL.LINES);
            for (var i = 0; i < lines; i++)
            {
                GL.Color(debugColors[i]);
                GL.Vertex(debugVertices[i * 2]);
                GL.Vertex(debugVertices[(i * 2) + 1]);
            }

            GL.End();
            GL.PopMatrix();
        }

        private void EnsureDebugMaterial()
        {
            if (debugMaterial != null)
            {
                return;
            }

            var shader = Shader.Find("Hidden/Internal-Colored");
            debugMaterial = new Material(shader) { hideFlags = HideFlags.HideAndDontSave };
            debugMaterial.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
            debugMaterial.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
            debugMaterial.SetInt("_Cull", (int)UnityEngine.Rendering.CullMode.Off);
            debugMaterial.SetInt("_ZWrite", 0);
            debugMaterial.SetInt("_ZTest", (int)UnityEngine.Rendering.CompareFunction.Always);
        }

        private void OnGUI()
        {
            var areaHeight = Mathf.Min(Screen.height - 24f, 560f);
            GUILayout.BeginArea(new Rect(12f, 12f, 520f, areaHeight), GUI.skin.window);
            GUILayout.Label("Rapier JS 3D Demos — Unity Component Layer");
            GUILayout.Label(status);
            GUILayout.Label($"Tick: {tick}  Hash: {lastHash:x16}");

            demoScroll = GUILayout.BeginScrollView(demoScroll);
            var nextIndex = GUILayout.SelectionGrid(selectedDemoIndex, DemoNames, 2);
            GUILayout.EndScrollView();
            if (nextIndex != selectedDemoIndex)
            {
                selectedDemoIndex = nextIndex;
                demo = DemoValues[selectedDemoIndex];
                RequestRebuild();
            }

            GUILayout.BeginHorizontal();
            if (GUILayout.Button(running ? "Pause" : "Run"))
            {
                running = !running;
            }

            if (GUILayout.Button("Restart"))
            {
                RequestRebuild();
            }
            GUILayout.EndHorizontal();

            debugDraw = GUILayout.Toggle(debugDraw, " Debug draw colliders");

            GUILayout.Label("Each body is a GameObject with Rapier components attached.");
            GUILayout.EndArea();
        }

        private void RequestRebuild()
        {
            status = "Rebuild requested.";
            rebuildRequested = true;
        }

        private void BuildDemo()
        {
            DestroyGeneratedRoot();
            fountainBodies.Clear();
            tick = 0;
            lastHash = 0;
            nextBodyId = 0;
            fountainSpawnCounter = 0;
            platformBody = null;
            platformPhase = 0f;
            characterController = null;
            pidBody = null;
            pidController = null;

            if (!TryProbeNative(out var nativeError))
            {
                running = false;
                status = nativeError;
                Debug.LogWarning(nativeError, this);
                return;
            }

            generatedRoot = new GameObject("Generated Rapier Component Demo");
            EnsureCameraAndLight();

            try
            {
                switch (demo)
                {
                    case DemoKind.Ccd:
                        BuildCcd();
                        break;
                    case DemoKind.Damping:
                        BuildDamping();
                        break;
                    case DemoKind.Fountain:
                        BuildFountain();
                        break;
                    case DemoKind.GlbToTrimesh:
                        BuildGlbToTrimesh();
                        break;
                    case DemoKind.GlbToConvexHull:
                        BuildGlbToConvexHull();
                        break;
                    case DemoKind.KevaTower:
                        BuildKevaTower();
                        break;
                    case DemoKind.Pyramid:
                        BuildPyramid();
                        break;
                    case DemoKind.CollisionGroups:
                        BuildCollisionGroups();
                        break;
                    case DemoKind.Joints:
                        BuildJoints();
                        break;
                    case DemoKind.Platform:
                        BuildPlatform();
                        break;
                    case DemoKind.LockedRotations:
                        BuildLockedRotations();
                        break;
                    case DemoKind.ConvexPolyhedron:
                        BuildConvexPolyhedron();
                        break;
                    case DemoKind.TriangleMesh:
                        BuildTriangleMesh();
                        break;
                    case DemoKind.Heightfield:
                        BuildHeightfield();
                        break;
                    case DemoKind.Voxels:
                        BuildVoxels();
                        break;
                    case DemoKind.CharacterController:
                        BuildCharacterController();
                        break;
                    case DemoKind.PidController:
                        BuildPidController();
                        break;
                    default:
                        running = false;
                        status = $"{DemoNames[selectedDemoIndex]} is not wired up.";
                        return;
                }

                running = true;
                status = $"{DemoNames[selectedDemoIndex]} loaded with Rapier components.";
            }
            catch (Exception ex) when (IsNativeLoadFailure(ex))
            {
                DestroyGeneratedRoot();
                running = false;
                status = "Rapier native plugin is not available. Build and copy rapier_unity_ffi for this platform.";
                Debug.LogWarning($"{status}\n{ex}", this);
            }
        }

        // ---- Demos -------------------------------------------------------------------------

        private void BuildPyramid()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("floor", RapierRigidBodyType.Fixed, new Vector3(0f, -0.1f, 0f), Quaternion.identity, new Vector3(30f, 0.1f, 30f), 0f, ColorFor("floor"));

            const float spacing = 1.25f;
            for (var layer = 0; layer < 10; layer++)
            {
                for (var row = layer; row < 10; row++)
                {
                    for (var col = layer; col < 10; col++)
                    {
                        var position = new Vector3(
                            layer * spacing / 2f + (col - layer) * spacing - 10f,
                            layer * spacing + 10f,
                            layer * spacing / 2f + (row - layer) * spacing - 10f);
                        CreateBox(NextId("pyramid-box"), RapierRigidBodyType.Dynamic, position, Quaternion.identity, Vector3.one * 0.5f, 1f, ColorFor("box"));
                    }
                }
            }

            LookAt(new Vector3(-32f, 20f, -28f), Vector3.zero);
        }

        private void BuildKevaTower()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("floor", RapierRigidBodyType.Fixed, new Vector3(0f, -0.1f, 0f), Quaternion.identity, new Vector3(50f, 0.1f, 50f), 0f, ColorFor("floor"));

            var block = new Vector3(0.1f, 0.5f, 2f);
            var columnsByTier = new[] { 0, 3, 5, 5, 7, 9 };
            var currentY = 0f;

            for (var tier = 5; tier >= 1; tier--)
            {
                var columns = columnsByTier[tier];
                var span = tier * block.z * 2f;
                CreateKevaStack(block, new Vector3(-span / 2f, currentY, -span / 2f), tier, columns, 3 * tier + 1);
                currentY += columns * block.y * 2f + 2f * block.x;
            }

            LookAt(new Vector3(-70f, 18f, 29f), new Vector3(0.6f, 3.1f, -0.3f));
        }

        private void CreateKevaStack(Vector3 block, Vector3 origin, int rows, int columns, int depth)
        {
            var countA = rows;
            var countB = depth;
            var span = 2f * block.z * rows;
            var height = 2f * block.y * columns;
            var pitch = (block.z * rows - block.x) / Mathf.Max(1, depth - 1);
            var shapes = new[]
            {
                block,
                new Vector3(block.z, block.y, block.x)
            };

            for (var layer = 0; layer < columns; layer++)
            {
                var swapped = countA;
                countA = countB;
                countB = swapped;

                var halfExtents = shapes[layer % 2];
                var layerY = halfExtents.y * layer * 2f;

                for (var a = 0; a < countA; a++)
                {
                    var x = layer % 2 == 0 ? pitch * a * 2f : halfExtents.x * a * 2f;
                    for (var b = 0; b < countB; b++)
                    {
                        var z = layer % 2 == 0 ? halfExtents.z * b * 2f : pitch * b * 2f;
                        var position = new Vector3(x + halfExtents.x + origin.x, layerY + halfExtents.y + origin.y, z + halfExtents.z + origin.z);
                        CreateBox(NextId("keva"), RapierRigidBodyType.Dynamic, position, Quaternion.identity, halfExtents, 1f, ColorFor("keva"));
                    }
                }
            }

            var cap = new Vector3(block.z, block.x, block.y);
            for (var x = 0; x < span / (2f * cap.x); x++)
            {
                for (var z = 0; z < span / (2f * cap.z); z++)
                {
                    var position = new Vector3(x * cap.x * 2f + cap.x + origin.x, cap.y + origin.y + height, z * cap.z * 2f + cap.z + origin.z);
                    CreateBox(NextId("keva-cap"), RapierRigidBodyType.Dynamic, position, Quaternion.identity, cap, 1f, ColorFor("keva"));
                }
            }
        }

        private void BuildDamping()
        {
            CreateWorld(Vector3.zero);

            const float fraction = 0.1f;
            for (var i = 0; i < 10; i++)
            {
                var sin = Mathf.Sin(i * fraction * Mathf.PI * 2f);
                var cos = Mathf.Cos(i * fraction * Mathf.PI * 2f);
                CreateBox(
                    NextId("damping-box"),
                    RapierRigidBodyType.Dynamic,
                    new Vector3(sin, cos, 0f),
                    Quaternion.identity,
                    Vector3.one * 0.2f,
                    1f,
                    ColorFor("box"),
                    new Vector3(10f * sin, 10f * cos, 0f),
                    new Vector3(0f, 0f, 100f),
                    (i + 1) * fraction * 10f,
                    (10 - i) * fraction * 10f);
            }

            LookAt(new Vector3(0f, 2f, 20f), new Vector3(0f, 2f, 0f));
        }

        private void BuildCcd()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("floor", RapierRigidBodyType.Fixed, new Vector3(0f, -0.1f, 0f), Quaternion.identity, new Vector3(30f, 0.1f, 30f), 0f, ColorFor("floor"));

            for (var wall = 0; wall < 5; wall++)
            {
                CreateCcdWall(new Vector3(6f * wall, 0.6f, 0f), 8);
            }

            CreateSphere(
                "ccd-ball",
                RapierRigidBodyType.Dynamic,
                new Vector3(-20f, 2.6f, 0f),
                1f,
                10f,
                ColorFor("sphere"),
                new Vector3(1000f, 0f, 0f),
                Vector3.zero,
                0f,
                0f,
                true);

            LookAt(new Vector3(-32f, 20f, -28f), Vector3.zero);
        }

        private void CreateCcdWall(Vector3 origin, int count)
        {
            for (var row = 0; row < count; row++)
            {
                for (var col = row; col < count; col++)
                {
                    var position = new Vector3(origin.x, origin.y + row, origin.z + 2f * col - row - count);
                    CreateBox(NextId("ccd-wall"), RapierRigidBodyType.Dynamic, position, Quaternion.identity, new Vector3(0.5f, 0.5f, 1f), 1f, ColorFor("box"));
                }
            }
        }

        private void BuildFountain()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("floor", RapierRigidBodyType.Fixed, Vector3.zero, Quaternion.identity, new Vector3(40f, 0.1f, 40f), 0f, ColorFor("floor"));
            LookAt(new Vector3(-88f, 47f, 84f), new Vector3(0f, 10f, 0f));
        }

        private void PreStepFountain()
        {
            const int spawnInterval = 5;
            var position = new Vector3(0f, 10f, 0f);
            var velocity = new Vector3(0f, 15f, 0f);

            fountainSpawnCounter++;
            if (fountainSpawnCounter % spawnInterval != 0)
            {
                return;
            }

            var shapeIndex = (fountainSpawnCounter / spawnInterval) % 4;
            RapierRigidBodyComponent body;
            switch (shapeIndex)
            {
                case 0:
                    body = CreateBox(NextId("fountain-box"), RapierRigidBodyType.Dynamic, position, Quaternion.identity, Vector3.one, 1f, ColorFor("box"), velocity);
                    break;
                case 1:
                    body = CreateSphere(NextId("fountain-sphere"), RapierRigidBodyType.Dynamic, position, 1f, 1f, ColorFor("sphere"), velocity, Vector3.zero, 0f, 0f, false);
                    break;
                case 2:
                    body = CreateConvexCylinderBody(NextId("fountain-cylinder"), position, 1f, ColorFor("capsule"), velocity);
                    break;
                default:
                    body = CreateConvexConeBody(NextId("fountain-cone"), position, 1f, ColorFor("keva"), velocity);
                    break;
            }

            fountainBodies.Enqueue(body.gameObject);
            while (fountainBodies.Count > Mathf.Max(1, maxFountainBodies))
            {
                var oldest = fountainBodies.Dequeue();
                if (oldest != null)
                {
                    Destroy(oldest);
                }
            }
        }

        private void BuildGlbToTrimesh()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("glb-ground", RapierRigidBodyType.Fixed, Vector3.zero, Quaternion.identity, new Vector3(5f, 0.1f, 5f), 0f, ColorFor("floor"));

            var vertices = RapierComponentDemosSuzanneMesh.CreateVertices();
            var indices = RapierComponentDemosSuzanneMesh.CreateIndices();
            CreateTrimeshGround("glb-trimesh-suzanne", vertices, indices, ColorFor("keva"));

            LookAt(new Vector3(10f, 5f, 10f), Vector3.zero);
        }

        private void BuildGlbToConvexHull()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("glb-convex-ground", RapierRigidBodyType.Fixed, Vector3.zero, Quaternion.identity, new Vector3(5f, 0.1f, 5f), 0f, ColorFor("floor"));

            var vertices = RapierComponentDemosSuzanneMesh.CreateVertices();
            var indices = RapierComponentDemosSuzanneMesh.CreateIndices();
            CreateConvexHullStatic("glb-convex-suzanne", vertices, vertices, indices, ColorFor("keva"));

            LookAt(new Vector3(10f, 5f, 10f), Vector3.zero);
        }

        private void BuildCollisionGroups()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateCollisionGroupsGround();

            var color1 = new Color(0.37f, 0.73f, 0.38f);
            var color2 = new Color(0.16f, 0.52f, 0.92f);

            const int count = 8;
            const float radius = 0.1f;
            const int layers = 4;
            var shift = radius * 2f;
            var center = shift * (count / 2f);

            for (var layer = 0; layer < layers; layer++)
            {
                for (var xIndex = 0; xIndex < count; xIndex++)
                {
                    for (var zIndex = 0; zIndex < count; zIndex++)
                    {
                        var even = zIndex % 2 == 0;
                        var color = even ? color1 : color2;
                        var position = new Vector3(
                            xIndex * shift - center,
                            layer * shift + 2.5f,
                            zIndex * shift - center);

                        var box = CreateBox(
                            NextId("group-box"),
                            RapierRigidBodyType.Dynamic,
                            position,
                            Quaternion.identity,
                            Vector3.one * radius,
                            1f,
                            color);
                        var groupBit = even ? (ushort)0x0001 : (ushort)0x0002;
                        GetCollider<RapierBoxCollider>(box).SetAuthoredCollisionGroups(groupBit, groupBit);
                    }
                }
            }

            LookAt(new Vector3(10f, 5f, 10f), Vector3.zero);
        }

        private void CreateCollisionGroupsGround()
        {
            var go = NewBodyObject("collision-groups-ground", Vector3.zero, Quaternion.identity);
            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, RapierRigidBodyType.Fixed, Vector3.zero, Vector3.zero, 0f, 0f, false);

            AddBoxCollider(go, new Vector3(5f, 0.1f, 5f), Vector3.zero, 0f, 0xFFFF, 0xFFFF);
            AddBoxCollider(go, new Vector3(1f, 0.1f, 1f), new Vector3(0f, 1f, 0f), 0f, 0x0001, 0x0001);
            AddBoxCollider(go, new Vector3(1f, 0.1f, 1f), new Vector3(0f, 2f, 0f), 0f, 0x0002, 0x0002);

            CreateBoxVisualChild(go, "floor", new Vector3(5f, 0.1f, 5f), Vector3.zero, ColorFor("floor"));
            CreateBoxVisualChild(go, "floor-1", new Vector3(1f, 0.1f, 1f), new Vector3(0f, 1f, 0f), new Color(0.37f, 0.73f, 0.38f));
            CreateBoxVisualChild(go, "floor-2", new Vector3(1f, 0.1f, 1f), new Vector3(0f, 2f, 0f), new Color(0.16f, 0.52f, 0.92f));

            go.SetActive(true);
        }

        private void BuildJoints()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreatePrismaticJointChain(new Vector3(20f, 10f, 0f), 5);
            CreateFixedJointGrid(new Vector3(0f, 10f, 0f), 5);
            CreateRevoluteJointChain(new Vector3(20f, 0f, 0f), 3);
            CreateSphericalJointGrid(15);

            LookAt(new Vector3(15f, 5f, 42f), new Vector3(13f, 1f, 1f));
        }

        private void CreatePrismaticJointChain(Vector3 origin, int count)
        {
            const float radius = 0.4f;
            const float shift = 1.0f;

            var parent = CreateBox(NextId("prismatic-anchor"), RapierRigidBodyType.Fixed, origin, Quaternion.identity, Vector3.one * radius, 0f, ColorFor("floor"));

            for (var i = 0; i < count; i++)
            {
                var position = new Vector3(origin.x, origin.y, origin.z + (i + 1) * shift);
                var child = CreateBox(NextId("prismatic-link"), RapierRigidBodyType.Dynamic, position, Quaternion.identity, Vector3.one * radius, 1f, ColorFor("box"));
                var axis = i % 2 == 0 ? new Vector3(1f, 1f, 0f) : new Vector3(-1f, 1f, 0f);
                var joint = AddJoint<RapierPrismaticJointComponent>(parent, child, Vector3.zero, new Vector3(0f, 0f, -shift));
                joint.Axis = axis;
                joint.gameObject.SetActive(true);
                joint.SetLimits(RapierJointAxis.LinearX, -2f, 2f);
                parent = child;
            }
        }

        private void CreateRevoluteJointChain(Vector3 origin, int count)
        {
            const float radius = 0.4f;
            const float shift = 2.0f;

            var parent = CreateBox(NextId("revolute-anchor"), RapierRigidBodyType.Fixed, new Vector3(origin.x, origin.y, 0f), Quaternion.identity, Vector3.one * radius, 0f, ColorFor("floor"));

            for (var i = 0; i < count; i++)
            {
                var z = origin.z + i * shift * 2f + shift;
                var positions = new[]
                {
                    new Vector3(origin.x, origin.y, z),
                    new Vector3(origin.x + shift, origin.y, z),
                    new Vector3(origin.x + shift, origin.y, z + shift),
                    new Vector3(origin.x, origin.y, z + shift)
                };

                var links = new RapierRigidBodyComponent[4];
                for (var k = 0; k < links.Length; k++)
                {
                    links[k] = CreateBox(NextId("revolute-link"), RapierRigidBodyType.Dynamic, positions[k], Quaternion.identity, Vector3.one * radius, 1f, ColorFor("box"));
                }

                CreateRevolute(parent, links[0], Vector3.zero, new Vector3(0f, 0f, -shift), Vector3.forward);
                CreateRevolute(links[0], links[1], Vector3.zero, new Vector3(-shift, 0f, 0f), Vector3.right);
                CreateRevolute(links[1], links[2], Vector3.zero, new Vector3(0f, 0f, -shift), Vector3.forward);
                CreateRevolute(links[2], links[3], Vector3.zero, new Vector3(shift, 0f, 0f), Vector3.right);
                parent = links[3];
            }
        }

        private void CreateRevolute(RapierRigidBodyComponent a, RapierRigidBodyComponent b, Vector3 anchor1, Vector3 anchor2, Vector3 axis)
        {
            var joint = AddJoint<RapierRevoluteJointComponent>(a, b, anchor1, anchor2);
            joint.Axis = axis;
            joint.gameObject.SetActive(true);
        }

        private void CreateFixedJointGrid(Vector3 origin, int count)
        {
            const float radius = 0.4f;
            const float shift = 1.0f;
            var parents = new List<RapierRigidBodyComponent>(count * count);

            for (var k = 0; k < count; k++)
            {
                for (var i = 0; i < count; i++)
                {
                    var fixedBody = i == 0 && ((k % 4 == 0 && k != count - 2) || k == count - 1);
                    var child = CreateSphere(
                        NextId("fixed-joint-node"),
                        fixedBody ? RapierRigidBodyType.Fixed : RapierRigidBodyType.Dynamic,
                        new Vector3(origin.x + k * shift, origin.y, origin.z + i * shift),
                        radius,
                        fixedBody ? 0f : 1f,
                        fixedBody ? ColorFor("floor") : ColorFor("sphere"),
                        Vector3.zero,
                        Vector3.zero,
                        0f,
                        0f,
                        false);

                    if (i > 0)
                    {
                        AddJoint<RapierFixedJointComponent>(parents[parents.Count - 1], child, Vector3.zero, new Vector3(0f, 0f, -shift)).gameObject.SetActive(true);
                    }

                    if (k > 0)
                    {
                        AddJoint<RapierFixedJointComponent>(parents[parents.Count - count], child, Vector3.zero, new Vector3(-shift, 0f, 0f)).gameObject.SetActive(true);
                    }

                    parents.Add(child);
                }
            }
        }

        private void CreateSphericalJointGrid(int count)
        {
            const float radius = 0.4f;
            const float shift = 1.0f;
            var parents = new List<RapierRigidBodyComponent>(count * count);

            for (var k = 0; k < count; k++)
            {
                for (var i = 0; i < count; i++)
                {
                    var fixedBody = i == 0 && (k % 4 == 0 || k == count - 1);
                    var child = CreateSphere(
                        NextId("spherical-joint-node"),
                        fixedBody ? RapierRigidBodyType.Fixed : RapierRigidBodyType.Dynamic,
                        new Vector3(k * shift, 0f, i * shift),
                        radius,
                        fixedBody ? 0f : 1f,
                        fixedBody ? ColorFor("floor") : ColorFor("sphere"),
                        Vector3.zero,
                        Vector3.zero,
                        0f,
                        0f,
                        false);

                    if (i > 0)
                    {
                        AddJoint<RapierSphericalJointComponent>(parents[parents.Count - 1], child, Vector3.zero, new Vector3(0f, 0f, -shift)).gameObject.SetActive(true);
                    }

                    if (k > 0)
                    {
                        AddJoint<RapierSphericalJointComponent>(parents[parents.Count - count], child, Vector3.zero, new Vector3(-shift, 0f, 0f)).gameObject.SetActive(true);
                    }

                    parents.Add(child);
                }
            }
        }

        private void BuildPlatform()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));

            BuildPlatformMesh(out var vertices, out var indices, 20, 70f, 4f, 70f);
            platformBody = CreateTrimeshBody("platform-trimesh", RapierRigidBodyType.KinematicVelocityBased, vertices, indices, ColorFor("floor"));
            platformPhase = 0f;

            CreateStackedShapeGrid("platform-body", 4, 10, 1f, 3f);

            LookAt(new Vector3(-88.48024f, 46.91133f, 83.56055f), Vector3.zero);
        }

        private void PreStepPlatform()
        {
            if (platformBody == null || !platformBody.IsRegistered)
            {
                return;
            }

            platformPhase += 0.016f;
            platformBody.SetLinearVelocity(new Vector3(0f, Mathf.Sin(platformPhase) * 10f, 0f));
            platformBody.SetAngularVelocity(new Vector3(0f, Mathf.Sin(platformPhase) * 0.2f, 0f));
        }

        private void BuildLockedRotations()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            const float groundHeight = 0.1f;
            CreateBox("floor", RapierRigidBodyType.Fixed, new Vector3(0f, -groundHeight, 0f), Quaternion.identity, new Vector3(1.7f, groundHeight, 1.7f), 0f, ColorFor("floor"));

            var xRotor = CreateBox("locked-x-rotor", RapierRigidBodyType.Dynamic, new Vector3(0f, 3f, 0f), Quaternion.identity, new Vector3(0.2f, 0.6f, 2f), 1f, ColorFor("box"));
            xRotor.SetEnabledTranslations(false, false, false);
            xRotor.SetEnabledRotations(true, false, false);

            var lockedCylinder = CreateConvexCylinderBody("locked-cylinder", new Vector3(0.2f, 5f, 0.4f), 0.4f, ColorFor("capsule"), Vector3.zero, 0.6f);
            lockedCylinder.SetEnabledRotations(false, false, false);

            LookAt(new Vector3(-10f, 3f, 0f), new Vector3(0f, 3f, 0f));
        }

        private void BuildConvexPolyhedron()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            BuildPlatformMesh(out var vertices, out var indices, 20, 40f, 4f, 40f);
            CreateTrimeshBody("convex-ground", RapierRigidBodyType.Fixed, vertices, indices, ColorFor("floor"));

            const int columns = 5;
            const int layers = 15;
            const float scale = 2f;
            const float borderRadius = 0.1f;
            var shift = borderRadius * 2f + scale;
            var centerX = shift * (columns / 2f);
            var centerY = shift * 0.5f;
            var centerZ = shift * (columns / 2f);
            var randomState = 0x636f6e76u;

            for (var layer = 0; layer < layers; layer++)
            {
                for (var xIndex = 0; xIndex < columns; xIndex++)
                {
                    for (var zIndex = 0; zIndex < columns; zIndex++)
                    {
                        var position = new Vector3(
                            xIndex * shift - centerX,
                            layer * shift + centerY + 3f,
                            zIndex * shift - centerZ);
                        var points = RandomConvexPoints(ref randomState, 10, scale);
                        CreateConvexBody(NextId("convex"), position, points, ColorFor("sphere"), scale * 0.5f);
                    }
                }
            }

            LookAt(new Vector3(-88.48024f, 46.91133f, 83.56055f), Vector3.zero);
        }

        private void BuildTriangleMesh()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            BuildPlatformMesh(out var vertices, out var indices, 20, 70f, 4f, 70f);
            CreateTrimeshBody("trimesh-ground", RapierRigidBodyType.Fixed, vertices, indices, ColorFor("floor"));

            CreateStackedShapeGrid("trimesh-body", 4, 10, 1f, 3f);

