        private void BuildCharacterController()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("floor", RapierRigidBodyType.Fixed, Vector3.zero, Quaternion.identity, new Vector3(15f, 0.1f, 15f), 0f, ColorFor("floor"));
            CreateControlBlocks("character-block");

            const float halfHeight = 1.2f;
            const float radius = 0.6f;
            var characterBody = CreateCapsule("character", RapierRigidBodyType.KinematicPositionBased, new Vector3(-10f, 4f, -10f), halfHeight, radius, 1f, ColorFor("capsule"), Vector3.zero);

            characterController = characterBody.gameObject.AddComponent<RapierCharacterControllerComponent>();
            characterController.RigidBody = characterBody;
            characterController.ShapeType = RapierShapeType.Capsule;
            characterController.HalfHeight = halfHeight;
            characterController.Radius = radius;
            characterController.Controller = BuildCharacterControllerSettings();
            characterController.ExcludeOwnBody = true;

            LookAt(new Vector3(-40f, 19.73f, 0f), new Vector3(0f, -0.4126f, 0f));
        }

        private static RapierCharacterController BuildCharacterControllerSettings()
        {
            var controller = RapierCharacterController.Default;
            controller.AutostepEnabled = true;
            controller.AutostepMaxHeight = 0.7f;
            controller.AutostepMinWidth = 0.3f;
            controller.AutostepIncludeDynamicBodies = true;
            controller.SnapToGroundEnabled = true;
            controller.SnapToGroundDistance = 0.7f;
            return controller;
        }

        private void PreStepCharacter()
        {
            if (characterController == null)
            {
                return;
            }

            const float speed = 0.2f;
            var desired = new Vector3(0f, Input.GetKey(KeyCode.Space) ? speed : -speed, 0f);

            if (Input.GetKey(KeyCode.UpArrow))
            {
                desired.x = speed;
            }
            else if (Input.GetKey(KeyCode.DownArrow))
            {
                desired.x = -speed;
            }

            if (Input.GetKey(KeyCode.LeftArrow))
            {
                desired.z = -speed;
            }
            else if (Input.GetKey(KeyCode.RightArrow))
            {
                desired.z = speed;
            }

            characterController.Move(desired, Mathf.Max(0.0001f, timestep));
        }

        private void BuildPidController()
        {
            CreateWorld(new Vector3(0f, -9.81f, 0f));
            CreateBox("floor", RapierRigidBodyType.Fixed, Vector3.zero, Quaternion.identity, new Vector3(15f, 0.1f, 15f), 0f, ColorFor("floor"));
            CreateControlBlocks("pid-block");

            pidBody = CreateConvexCylinderBody("pid-character", new Vector3(-10f, 4f, -10f), 0.6f, ColorFor("capsule"), Vector3.zero, 1.2f);
            pidBody.SetGravityScale(10f);
            pidBody.SetSoftCcdPrediction(10f);

            pidController = pidBody.gameObject.AddComponent<RapierPidControllerComponent>();
            pidController.RigidBody = pidBody;
            pidController.Kp = 60f;
            pidController.Ki = 0f;
            pidController.Kd = 1f;
            pidController.Axes = RapierPidAxesMask.AllAng;

            LookAt(new Vector3(-40f, 19.73f, 0f), new Vector3(0f, -0.4126f, 0f));
        }

        private void PreStepPidController()
        {
            if (pidBody == null || !pidBody.IsRegistered || pidController == null)
            {
                return;
            }

            const float speed = 0.2f;
            var dir = Vector3.zero;

            if (Input.GetKey(KeyCode.UpArrow))
            {
                dir.x = speed;
            }
            else if (Input.GetKey(KeyCode.DownArrow))
            {
                dir.x = -speed;
            }

            if (Input.GetKey(KeyCode.LeftArrow))
            {
                dir.z = -speed;
            }
            else if (Input.GetKey(KeyCode.RightArrow))
            {
                dir.z = speed;
            }

            if (Input.GetKey(KeyCode.Space))
            {
                dir.y = speed;
            }

            if (dir == Vector3.zero)
            {
                pidController.Axes = RapierPidAxesMask.AllAng;
            }
            else if (Mathf.Approximately(dir.y, 0f))
            {
                pidController.Axes = RapierPidAxesMask.AllAng | RapierPidAxesMask.LinX | RapierPidAxesMask.LinZ;
            }
            else
            {
                pidController.Axes = RapierPidAxesMask.All;
            }

            if (!pidBody.TryGetTransform(out var current))
            {
                return;
            }

            pidController.ApplyLinearCorrection(current.Position + dir, Vector3.zero);
            pidController.ApplyAngularCorrection(Quaternion.identity, Vector3.zero);
        }

        // Shared block grid used by the character-controller and PID demos.
        private void CreateControlBlocks(string idPrefix)
        {
            const float radius = 0.5f;
            const int count = 5;
            var shift = radius * 2.5f;
            var center = count * radius;
            const float height = 5f;

            for (var layer = 0; layer < count; layer++)
            {
                for (var row = layer; row < count; row++)
                {
                    for (var column = layer; column < count; column++)
                    {
                        var position = new Vector3(
                            layer * shift * 0.5f + (column - layer) * shift - center,
                            layer * shift * 0.5f + height,
                            layer * shift * 0.5f + (row - layer) * shift - center);
                        CreateBox(NextId(idPrefix), RapierRigidBodyType.Dynamic, position, Quaternion.identity, new Vector3(radius, radius * 0.5f, radius), 1f, ColorFor("box"));
                    }
                }
            }
        }

        private void CreateStackedShapeGrid(string idPrefix, int columns, int layers, float radius, float baseHeight)
        {
            var shift = radius * 3f;
            var centerY = shift * 0.5f;
            var offset = -columns * shift * 0.5f;

            for (var layer = 0; layer < layers; layer++)
            {
                for (var xIndex = 0; xIndex < columns; xIndex++)
                {
                    for (var zIndex = 0; zIndex < columns; zIndex++)
                    {
                        var position = new Vector3(
                            xIndex * shift + offset,
                            layer * shift + centerY + baseHeight,
                            zIndex * shift + offset);
                        CreateStackBody(NextId(idPrefix), layer % 5, position, radius);
                    }
                }

                offset -= 0.05f * radius * (columns - 1f);
            }
        }

        private RapierRigidBodyComponent CreateStackBody(string id, int shapeKind, Vector3 position, float radius)
        {
            switch (shapeKind)
            {
                case 0:
                    return CreateBox(id, RapierRigidBodyType.Dynamic, position, Quaternion.identity, Vector3.one * radius, 1f, ColorFor("box"));
                case 1:
                    return CreateSphere(id, RapierRigidBodyType.Dynamic, position, radius, 1f, ColorFor("sphere"), Vector3.zero, Vector3.zero, 0f, 0f, false);
                case 2:
                    return CreateConvexCylinderBody(id, position, radius, ColorFor("capsule"), Vector3.zero);
                case 3:
                    return CreateConvexConeBody(id, position, radius, ColorFor("keva"), Vector3.zero);
                default:
                    return CreateCompoundBody(id, position, radius);
            }
        }

        // ---- Component body builders -------------------------------------------------------

        private RapierRigidBodyComponent CreateBox(
            string id,
            RapierRigidBodyType bodyType,
            Vector3 position,
            Quaternion rotation,
            Vector3 halfExtents,
            float density,
            Color color,
            Vector3 linearVelocity = default,
            Vector3 angularVelocity = default,
            float linearDamping = 0f,
            float angularDamping = 0f)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ConfigureVisual(go, id, position, rotation, halfExtents * 2f, color);

            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, bodyType, linearVelocity, angularVelocity, linearDamping, angularDamping, false);

            var collider = go.AddComponent<RapierBoxCollider>();
            collider.HalfExtents = halfExtents;
            collider.Density = density;

            go.SetActive(true);
            return body;
        }

        private RapierRigidBodyComponent CreateSphere(
            string id,
            RapierRigidBodyType bodyType,
            Vector3 position,
            float radius,
            float density,
            Color color,
            Vector3 linearVelocity,
            Vector3 angularVelocity,
            float linearDamping,
            float angularDamping,
            bool ccd)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            ConfigureVisual(go, id, position, Quaternion.identity, Vector3.one * radius * 2f, color);

            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, bodyType, linearVelocity, angularVelocity, linearDamping, angularDamping, ccd);

            var collider = go.AddComponent<RapierSphereCollider>();
            collider.Radius = radius;
            collider.Density = density;

            go.SetActive(true);
            return body;
        }

        private RapierRigidBodyComponent CreateCapsule(
            string id,
            RapierRigidBodyType bodyType,
            Vector3 position,
            float halfHeight,
            float radius,
            float density,
            Color color,
            Vector3 linearVelocity)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Capsule);
            var totalHeight = halfHeight * 2f + radius * 2f;
            ConfigureVisual(go, id, position, Quaternion.identity, new Vector3(radius * 2f, totalHeight / 2f, radius * 2f), color);

            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, bodyType, linearVelocity, Vector3.zero, 0f, 0f, false);

            var collider = go.AddComponent<RapierCapsuleCollider>();
            collider.HalfHeight = halfHeight;
            collider.Radius = radius;
            collider.Density = density;

            go.SetActive(true);
            return body;
        }

        private RapierRigidBodyComponent CreateConvexCylinderBody(string id, Vector3 position, float radius, Color color, Vector3 linearVelocity, float halfHeight = -1f)
        {
            const int segments = 16;
            var cylinderHalfHeight = halfHeight > 0f ? halfHeight : radius;
            BuildCylinderMesh(cylinderHalfHeight, radius, segments, out var vertices, out var indices);
            return CreateConvexBodyWithMesh(id, position, CylinderHullPoints(cylinderHalfHeight, radius, segments), vertices, indices, color, linearVelocity);
        }

        private RapierRigidBodyComponent CreateConvexConeBody(string id, Vector3 position, float radius, Color color, Vector3 linearVelocity)
        {
            const int segments = 16;
            BuildConeMesh(radius, segments, out var vertices, out var indices);
            return CreateConvexBodyWithMesh(id, position, ConeHullPoints(radius, segments), vertices, indices, color, linearVelocity);
        }

        private RapierRigidBodyComponent CreateConvexBody(string id, Vector3 position, Vector3[] points, Color color, float visualRadius)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            ConfigureVisual(go, id, position, Quaternion.identity, Vector3.one * visualRadius * 2f, color);

            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, RapierRigidBodyType.Dynamic, Vector3.zero, Vector3.zero, 0f, 0f, false);

            var collider = go.AddComponent<RapierConvexHullCollider>();
            collider.SetPoints(points);
            collider.Density = 1f;

            go.SetActive(true);
            return body;
        }

        private RapierRigidBodyComponent CreateConvexBodyWithMesh(string id, Vector3 position, Vector3[] hullPoints, Vector3[] vertices, int[] indices, Color color, Vector3 linearVelocity)
        {
            var go = NewBodyObject(id, position, Quaternion.identity);
            AddMeshVisual(go, vertices, indices, color);

            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, RapierRigidBodyType.Dynamic, linearVelocity, Vector3.zero, 0f, 0f, false);

            var collider = go.AddComponent<RapierConvexHullCollider>();
            collider.SetPoints(hullPoints);
            collider.Density = 1f;

            go.SetActive(true);
            return body;
        }

        private RapierRigidBodyComponent CreateCompoundBody(string id, Vector3 position, float radius)
        {
            var go = NewBodyObject(id, position, Quaternion.identity);
            var core = Vector3.one * (radius * 0.5f);
            var arm = new Vector3(radius * 0.5f, radius, radius * 0.5f);

            var body = go.AddComponent<RapierRigidBodyComponent>();
            ConfigureBody(body, RapierRigidBodyType.Dynamic, Vector3.zero, Vector3.zero, 0f, 0f, false);

            AddBoxCollider(go, core, Vector3.zero, 1f, 0xFFFF, 0xFFFF);
            AddBoxCollider(go, arm, new Vector3(radius, 0f, 0f), 1f, 0xFFFF, 0xFFFF);
            AddBoxCollider(go, arm, new Vector3(-radius, 0f, 0f), 1f, 0xFFFF, 0xFFFF);

            CreateBoxVisualChild(go, id + "-core", core, Vector3.zero, ColorFor("box"));
            CreateBoxVisualChild(go, id + "-arm-positive-x", arm, new Vector3(radius, 0f, 0f), ColorFor("box"));
            CreateBoxVisualChild(go, id + "-arm-negative-x", arm, new Vector3(-radius, 0f, 0f), ColorFor("box"));

            go.SetActive(true);
            return body;
        }

