        // ---- Component plumbing helpers ----------------------------------------------------

        private void CreateWorld(Vector3 gravity)
        {
            worldGo = new GameObject("Rapier World");
            worldGo.transform.SetParent(generatedRoot.transform, false);
            worldComponent = worldGo.AddComponent<RapierWorldComponent>();
            worldComponent.StepMode = RapierWorldStepMode.Manual;
            worldComponent.Gravity = gravity;
            worldComponent.Timestep = Mathf.Max(0.0001f, timestep);
        }

        private GameObject NewBodyObject(string id, Vector3 position, Quaternion rotation)
        {
            var go = new GameObject(id);
            go.SetActive(false);
            go.transform.SetParent(worldGo.transform, false);
            go.transform.SetPositionAndRotation(position, rotation);
            return go;
        }

        private void ConfigureVisual(GameObject go, string id, Vector3 position, Quaternion rotation, Vector3 scale, Color color)
        {
            go.name = id;
            go.SetActive(false);
            go.transform.SetParent(worldGo.transform, false);
            go.transform.SetPositionAndRotation(position, rotation);
            go.transform.localScale = scale;
            RemoveUnityCollider(go);
            SetColor(go, color);
        }

        private static void ConfigureBody(
            RapierRigidBodyComponent body,
            RapierRigidBodyType bodyType,
            Vector3 linearVelocity,
            Vector3 angularVelocity,
            float linearDamping,
            float angularDamping,
            bool ccd)
        {
            var dynamic = bodyType == RapierRigidBodyType.Dynamic;
            body.BodyType = bodyType;
            body.SyncTransformFromRapier = bodyType != RapierRigidBodyType.Fixed;
            body.CanSleep = dynamic;
            body.CcdEnabled = dynamic && ccd;
            body.InitialLinearVelocity = dynamic ? linearVelocity : Vector3.zero;
            body.InitialAngularVelocity = dynamic ? angularVelocity : Vector3.zero;
            body.LinearDamping = Mathf.Max(0f, linearDamping);
            body.AngularDamping = Mathf.Max(0f, angularDamping);
        }

        private static void AddBoxCollider(GameObject go, Vector3 halfExtents, Vector3 localPosition, float density, ushort memberships, ushort filter)
        {
            var collider = go.AddComponent<RapierBoxCollider>();
            collider.HalfExtents = halfExtents;
            collider.Density = density;
            collider.LocalPosition = localPosition;
            if (memberships != 0xFFFF || filter != 0xFFFF)
            {
                collider.SetAuthoredCollisionGroups(memberships, filter);
            }
        }

        private T AddJoint<T>(RapierRigidBodyComponent body1, RapierRigidBodyComponent body2, Vector3 anchor1, Vector3 anchor2)
            where T : RapierJointComponent
        {
            var go = new GameObject($"{typeof(T).Name}");
            go.SetActive(false);
            go.transform.SetParent(worldGo.transform, false);
            var joint = go.AddComponent<T>();
            joint.Body1 = body1;
            joint.Body2 = body2;
            joint.LocalAnchor1 = anchor1;
            joint.LocalAnchor2 = anchor2;
            return joint;
        }

        private static T GetCollider<T>(RapierRigidBodyComponent body) where T : RapierColliderComponent
        {
            return body.GetComponent<T>();
        }

        private void AddMeshVisual(GameObject go, Vector3[] vertices, int[] indices, Color color)
        {
            var mesh = new Mesh { name = go.name + "-mesh" };
            if (vertices.Length > 65000)
            {
                mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            }

            mesh.vertices = vertices;
            mesh.triangles = indices;
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();

            go.AddComponent<MeshFilter>().sharedMesh = mesh;
            go.AddComponent<MeshRenderer>().material = CreateMaterial(color);
        }

        private void CreateBoxVisualChild(GameObject parent, string id, Vector3 halfExtents, Vector3 localPosition, Color color)
        {
            var child = GameObject.CreatePrimitive(PrimitiveType.Cube);
            child.name = id;
            child.transform.SetParent(parent.transform, false);
            child.transform.localPosition = localPosition;
            child.transform.localRotation = Quaternion.identity;
            child.transform.localScale = halfExtents * 2f;
            RemoveUnityCollider(child);
            SetColor(child, color);
        }

        // ---- Geometry generation (shared with the low-level demo sample) -------------------

        private static Vector3[] CylinderHullPoints(float halfHeight, float radius, int segments)
        {
            var points = new Vector3[segments * 2];
            for (var i = 0; i < segments; i++)
            {
                var angle = Mathf.PI * 2f * i / segments;
                var x = Mathf.Cos(angle) * radius;
                var z = Mathf.Sin(angle) * radius;
                points[i] = new Vector3(x, halfHeight, z);
                points[i + segments] = new Vector3(x, -halfHeight, z);
            }

            return points;
        }

        private static Vector3[] ConeHullPoints(float radius, int segments)
        {
            var points = new Vector3[segments + 1];
            points[0] = new Vector3(0f, radius, 0f);
            for (var i = 0; i < segments; i++)
            {
                var angle = Mathf.PI * 2f * i / segments;
                points[i + 1] = new Vector3(Mathf.Cos(angle) * radius, -radius, Mathf.Sin(angle) * radius);
            }

            return points;
        }

        private static void BuildCylinderMesh(float halfHeight, float radius, int segments, out Vector3[] vertices, out int[] indices)
        {
            vertices = new Vector3[segments * 4 + 2];
            var topCenter = segments * 4;
            var bottomCenter = segments * 4 + 1;
            vertices[topCenter] = new Vector3(0f, halfHeight, 0f);
            vertices[bottomCenter] = new Vector3(0f, -halfHeight, 0f);

            for (var i = 0; i < segments; i++)
            {
                var angle = Mathf.PI * 2f * i / segments;
                var x = Mathf.Cos(angle) * radius;
                var z = Mathf.Sin(angle) * radius;
                var top = new Vector3(x, halfHeight, z);
                var bottom = new Vector3(x, -halfHeight, z);
                vertices[i] = top;
                vertices[segments + i] = bottom;
                vertices[segments * 2 + i] = top;
                vertices[segments * 3 + i] = bottom;
            }

            indices = new int[segments * 12];
            var t = 0;
            for (var i = 0; i < segments; i++)
            {
                var next = (i + 1) % segments;
                indices[t++] = i;
                indices[t++] = next;
                indices[t++] = segments + i;
                indices[t++] = next;
                indices[t++] = segments + next;
                indices[t++] = segments + i;

                indices[t++] = topCenter;
                indices[t++] = segments * 2 + next;
                indices[t++] = segments * 2 + i;

                indices[t++] = bottomCenter;
                indices[t++] = segments * 3 + i;
                indices[t++] = segments * 3 + next;
            }
        }

        private static void BuildConeMesh(float radius, int segments, out Vector3[] vertices, out int[] indices)
        {
            vertices = new Vector3[segments * 2 + 2];
            var apex = segments * 2;
            var baseCenter = segments * 2 + 1;
            vertices[apex] = new Vector3(0f, radius, 0f);
            vertices[baseCenter] = new Vector3(0f, -radius, 0f);

            for (var i = 0; i < segments; i++)
            {
                var angle = Mathf.PI * 2f * i / segments;
                var ring = new Vector3(Mathf.Cos(angle) * radius, -radius, Mathf.Sin(angle) * radius);
                vertices[i] = ring;
                vertices[segments + i] = ring;
            }

            indices = new int[segments * 6];
            var t = 0;
            for (var i = 0; i < segments; i++)
            {
                var next = (i + 1) % segments;
                indices[t++] = apex;
                indices[t++] = next;
                indices[t++] = i;

                indices[t++] = baseCenter;
                indices[t++] = segments + i;
                indices[t++] = segments + next;
            }
        }

        private static void BuildPlatformMesh(out Vector3[] vertices, out int[] indices, int subdivisions, float width, float height, float depth)
        {
            var vertexCount = subdivisions + 1;
            vertices = new Vector3[vertexCount * vertexCount];
            var elementWidth = 1f / subdivisions;
            var randomState = 0x7472696du;

            for (var row = 0; row <= subdivisions; row++)
            {
                for (var column = 0; column <= subdivisions; column++)
                {
                    var x = (column * elementWidth - 0.5f) * width;
                    var y = NextPlatformRandom(ref randomState) * height;
                    var z = (row * elementWidth - 0.5f) * depth;
                    vertices[row * vertexCount + column] = new Vector3(x, y, z);
                }
            }

            indices = new int[subdivisions * subdivisions * 6];
            var t = 0;
            for (var row = 0; row < subdivisions; row++)
            {
                for (var column = 0; column < subdivisions; column++)
                {
                    var i1 = row * vertexCount + column;
                    var i2 = row * vertexCount + column + 1;
                    var i3 = (row + 1) * vertexCount + column;
                    var i4 = (row + 1) * vertexCount + column + 1;
                    indices[t++] = i1;
                    indices[t++] = i3;
                    indices[t++] = i2;
                    indices[t++] = i3;
                    indices[t++] = i4;
                    indices[t++] = i2;
                }
            }
        }

        private static float NextPlatformRandom(ref uint state)
        {
            state = state * 1664525u + 1013904223u;
            return (state & 0x00ffffff) / 16777216f;
        }

        private static Vector3[] RandomConvexPoints(ref uint state, int count, float scale)
        {
            var points = new Vector3[count];
            for (var i = 0; i < points.Length; i++)
            {
                points[i] = new Vector3(
                    NextPlatformRandom(ref state) * scale,
                    NextPlatformRandom(ref state) * scale,
                    NextPlatformRandom(ref state) * scale);
            }

            return points;
        }

        private static Vector3[] GenerateVoxelPoints(int subdivisions)
        {
            var points = new Vector3[(subdivisions + 1) * (subdivisions + 1)];
            var index = 0;
            for (var i = 0; i <= subdivisions; i++)
            {
                for (var j = 0; j <= subdivisions; j++)
                {
                    var wave = Mathf.Sin((float)i / subdivisions * 10f) * Mathf.Cos((float)j / subdivisions * 10f);
                    var y = Mathf.Clamp(wave, -0.8f, 0.8f) * 8f;
                    points[index++] = new Vector3(i - subdivisions * 0.5f, y, j - subdivisions * 0.5f);
                }
            }

            return points;
        }

        private static void BuildVoxelMesh(Vector3[] points, Vector3 voxelSize, out Vector3[] vertices, out int[] indices)
        {
            var gridKeys = new List<Vector3Int>(points.Length);
            var seen = new HashSet<Vector3Int>();
            for (var i = 0; i < points.Length; i++)
            {
                var key = new Vector3Int(
                    Mathf.FloorToInt(points[i].x / voxelSize.x),
                    Mathf.FloorToInt(points[i].y / voxelSize.y),
                    Mathf.FloorToInt(points[i].z / voxelSize.z));
                if (seen.Add(key))
                {
                    gridKeys.Add(key);
                }
            }

            gridKeys.Sort(CompareVoxelKeys);

            var half = voxelSize * 0.5f;
            var faceOffsets = new[]
            {
                new[] { new Vector3(-half.x, -half.y, half.z), new Vector3(half.x, -half.y, half.z), new Vector3(half.x, half.y, half.z), new Vector3(-half.x, half.y, half.z) },
                new[] { new Vector3(half.x, -half.y, -half.z), new Vector3(-half.x, -half.y, -half.z), new Vector3(-half.x, half.y, -half.z), new Vector3(half.x, half.y, -half.z) },
                new[] { new Vector3(half.x, -half.y, half.z), new Vector3(half.x, -half.y, -half.z), new Vector3(half.x, half.y, -half.z), new Vector3(half.x, half.y, half.z) },
                new[] { new Vector3(-half.x, -half.y, -half.z), new Vector3(-half.x, -half.y, half.z), new Vector3(-half.x, half.y, half.z), new Vector3(-half.x, half.y, -half.z) },
                new[] { new Vector3(-half.x, half.y, half.z), new Vector3(half.x, half.y, half.z), new Vector3(half.x, half.y, -half.z), new Vector3(-half.x, half.y, -half.z) },
                new[] { new Vector3(-half.x, -half.y, -half.z), new Vector3(half.x, -half.y, -half.z), new Vector3(half.x, -half.y, half.z), new Vector3(-half.x, -half.y, half.z) }
            };

            vertices = new Vector3[gridKeys.Count * 24];
            indices = new int[gridKeys.Count * 36];
            var vertex = 0;
            var index = 0;
            for (var i = 0; i < gridKeys.Count; i++)
            {
                var center = VoxelCenter(gridKeys[i], voxelSize);
                for (var face = 0; face < faceOffsets.Length; face++)
                {
                    var baseVertex = vertex;
                    for (var corner = 0; corner < 4; corner++)
                    {
                        vertices[vertex++] = center + faceOffsets[face][corner];
                    }

                    indices[index++] = baseVertex;
                    indices[index++] = baseVertex + 1;
                    indices[index++] = baseVertex + 2;
                    indices[index++] = baseVertex;
                    indices[index++] = baseVertex + 2;
                    indices[index++] = baseVertex + 3;
                }
            }
        }

        private static int CompareVoxelKeys(Vector3Int a, Vector3Int b)
        {
            var x = a.x.CompareTo(b.x);
            if (x != 0)
            {
                return x;
            }

            var y = a.y.CompareTo(b.y);
            return y != 0 ? y : a.z.CompareTo(b.z);
        }

        private static Vector3 VoxelCenter(Vector3Int key, Vector3 voxelSize)
        {
            return new Vector3(
                (key.x + 0.5f) * voxelSize.x,
                (key.y + 0.5f) * voxelSize.y,
                (key.z + 0.5f) * voxelSize.z);
        }

        private static void BuildHeightfieldMesh(float[] heights, int rows, int columns, Vector3 scale, out Vector3[] vertices, out int[] indices)
        {
            vertices = new Vector3[rows * columns];
            for (var r = 0; r < rows; r++)
            {
                for (var c = 0; c < columns; c++)
                {
                    var x = ((float)c / (columns - 1) - 0.5f) * scale.x;
                    var z = ((float)r / (rows - 1) - 0.5f) * scale.z;
                    var y = heights[r * columns + c] * scale.y;
                    vertices[r * columns + c] = new Vector3(x, y, z);
                }
            }

            indices = BuildGridIndices(rows, columns);
        }

        private static int[] BuildGridIndices(int rows, int columns)
        {
            var indices = new int[(rows - 1) * (columns - 1) * 6];
            var t = 0;
            for (var r = 0; r < rows - 1; r++)
            {
                for (var c = 0; c < columns - 1; c++)
                {
                    var i0 = r * columns + c;
                    var i1 = r * columns + c + 1;
                    var i2 = (r + 1) * columns + c;
                    var i3 = (r + 1) * columns + c + 1;
                    indices[t++] = i0;
                    indices[t++] = i2;
                    indices[t++] = i1;
                    indices[t++] = i1;
                    indices[t++] = i2;
                    indices[t++] = i3;
                }
            }

            return indices;
        }

        // ---- Misc helpers ------------------------------------------------------------------

        private static Material CreateMaterial(Color color)
        {
            var shader = Shader.Find("Standard")
                ?? Shader.Find("Universal Render Pipeline/Lit")
                ?? Shader.Find("Sprites/Default");
            return new Material(shader) { color = color };
        }

        private string NextId(string prefix)
        {
            nextBodyId++;
            return $"{prefix}-{nextBodyId:0000}";
        }

        private static int IndexOf(DemoKind value)
        {
            for (var i = 0; i < DemoValues.Length; i++)
            {
                if (DemoValues[i] == value)
                {
                    return i;
                }
            }

            return 0;
        }

        private static Color ColorFor(string role)
        {
            switch (role)
            {
                case "floor":
                    return new Color(0.28f, 0.32f, 0.36f);
                case "sphere":
                    return new Color(0.16f, 0.52f, 0.92f);
                case "capsule":
                    return new Color(0.37f, 0.73f, 0.38f);
                case "keva":
                    return new Color(0.86f, 0.63f, 0.35f);
                default:
                    return new Color(0.95f, 0.55f, 0.18f);
            }
        }

        private void EnsureCameraAndLight()
        {
            var camera = Camera.main;
            if (camera == null)
            {
                var cameraObject = new GameObject("Rapier Demo Camera");
                cameraObject.transform.SetParent(generatedRoot.transform, false);
                camera = cameraObject.AddComponent<Camera>();
                cameraObject.tag = "MainCamera";
            }

            if (UnityEngine.Object.FindObjectOfType<Light>() == null)
            {
                var lightObject = new GameObject("Rapier Demo Light");
                lightObject.transform.SetParent(generatedRoot.transform, false);
                var light = lightObject.AddComponent<Light>();
                light.type = LightType.Directional;
                light.intensity = 1.1f;
                lightObject.transform.rotation = Quaternion.Euler(50f, -30f, 0f);
            }
        }

        private static void LookAt(Vector3 eye, Vector3 target)
        {
            var camera = Camera.main;
            if (camera == null)
            {
                return;
            }

            camera.transform.position = eye;
            camera.transform.LookAt(target);
            camera.nearClipPlane = 0.01f;
            camera.farClipPlane = 500f;
        }

        private static bool TryProbeNative(out string error)
        {
            try
            {
                using (var probe = RapierWorld.Create())
                {
                    probe.SetGravity(Vector3.zero);
                    probe.SetTimestep(1f / 60f);
                }

                error = null;
                return true;
            }
            catch (Exception ex) when (IsNativeFailure(ex))
            {
                error = "Rapier native plugin is not available. Build and copy rapier_unity_ffi for this platform.";
                return false;
            }
        }

        private static bool IsNativeFailure(Exception ex)
        {
            return ex is DllNotFoundException
                || ex is EntryPointNotFoundException
                || ex is BadImageFormatException
                || ex is InvalidOperationException;
        }

        private static bool IsNativeLoadFailure(Exception ex)
        {
            return ex is DllNotFoundException
                || ex is EntryPointNotFoundException
                || ex is BadImageFormatException;
        }

        private static void RemoveUnityCollider(GameObject gameObject)
        {
            var unityCollider = gameObject.GetComponent<Collider>();
            if (unityCollider != null)
            {
                UnityEngine.Object.Destroy(unityCollider);
            }
        }

        private static void SetColor(GameObject gameObject, Color color)
        {
            var renderer = gameObject.GetComponent<MeshRenderer>();
            if (renderer != null)
            {
                renderer.material.color = color;
            }
        }

        private void DestroyGeneratedRoot()
        {
            if (generatedRoot != null)
            {
                Destroy(generatedRoot);
                generatedRoot = null;
            }

            worldGo = null;
            worldComponent = null;
        }
    }
}
